document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector("[data-nav-toggle]"),t=document.getElementById("menu-principal");e&&t&&e.addEventListener("click",()=>{const l=t.classList.toggle("open");e.setAttribute("aria-expanded",l?"true":"false")}),document.querySelectorAll(".js-slider").forEach(e=>{const t=[...e.querySelectorAll(".slide")],l=[...e.querySelectorAll(".dots button")];if(!t.length)return;let n=0;function c(e){n=(e+t.length)%t.length,t.forEach((e,t)=>e.classList.toggle("active",t===n)),l.forEach((e,t)=>e.classList.toggle("active",t===n))}l.forEach((e,t)=>e.addEventListener("click",()=>c(t))),c(0),setInterval(()=>c(n+1),3600)})});